      "title": "落款与正文气息贯通",
      "font": "楷书",
      "detail": "落款不是独立的一块。八大山人、王铎的作品里，落款在空间、笔法、气息上都与正文契合，看过去完全分不开它是单独成立的。初学写落款之所以产生强烈的「分离感」，是因为字形写法与整张章法都还没处理好，缺少章法上的统一性。",
      "certainty": "inferred",
