      "title": "印泥常见两种：朱砂印泥多用于楷书隶书，朱膘印泥多用于行书草书",
      "font": "楷书",
      "detail": "朱砂印泥是用漂制朱砂时沉淀在乳薄最下层的朱砂制作而成，其色深棕红、厚重沉着，多用于楷书、隶书；朱膘印泥是用漂至上层的朱砂细末调制而成，其色略显橘红、细腻雅致，多用于行书、草书。（字幕作「朱标」，同句另有「朱膘印泥」可自证，修正为「朱膘」；「乳薄」疑为「乳钵」，未确证，保留原词。）",
