      "title": "上杆之前先砑光：用鹅卵石压磨背面，使书画背面光滑平整、易于舒卷",
      "font": "楷书",
      "detail": "在上杆之前还要用光滑的鹅卵石在裱背（字幕作「表镜」）的背面压磨几遍，称为「砑光」（字幕作「亚光或亚活」）。只有经过砑光才能使书画的背面光滑平整，易于舒卷（字幕作「书卷」）。最后再装上制好的轴杆，书画作品就装裱完成了。",
