      "font": "楷书",
      "detail": "现代书画一般将画心装裱成镜心，小幅可入框，稍加装饰即可用于室内装饰；若裱成大件也可以直接贴墙而挂。操作方法多样，适用于不同尺寸形状的画芯，是一种简易且方便的装裱形式。（字幕作「静心」「镜片」「表片」「小表」「表成」，据上下文修正为「镜心」「裱片」「裱成」；同段「画芯」按「画心」统一。）",
