      "detail": "中间是作品，与作品两头相连的是隔水；后有拖尾和地头；天头一般用深色香料（疑为「深色绫料」，未确证），作用是装饰和保护画心；引首一般用于题写。两个隔水是为了使天头、引首以及拖尾分清眉目、增加美感，所以材质多采用浅色绫；而拖尾一般选用风格古旧的宣纸，是留给鉴赏者用来题词的。最后还有地头，它和天头有一样的作用，就是装饰和保护画心。（字幕作「银手」「添头」，按同音修正为「引首」「天头」。）",
