      "detail": "创作遇到字帖里没有的字，按四级往下找：**①** 有的直接往里带；**②** 没有的找本人写的其他碑帖（如颜真卿写《多宝塔》，若《多宝塔》里没有，就找他另一块碑改一下——字幕作「千里碑」，疑为《颜勤礼碑》，存疑）；**③** 本人没有的，找学他的、或跟他相似的书体（颜真卿里没有的去找柳公权）；**④** 什么都没有了，就结合笔画改字。这四步就是「拼接」，是创作的基本流程。注意：在外面给人写作品时还去集字，「是不是有点太过丢人了」——集字是学习手段，不是成品状态。",
