      "detail": "古典派审美里字如其人一直贯穿：欣赏艺术要看人品，讲的是才德兼备、先学做人再学文化课——这是儒家的观点（《论语》「行有余力，则以学文」），所以做人在书法的评价体系里是一非常重要的一环。张孟頫作为宋朝汉人降了元朝，后人诟病很多；前清的王铎、宋四家里的蔡京（老师口述作「蔡希」，指蔡襄）也一样——人品一败坏，后面的抨击就多，更别说去推崇他的艺术作品。",
