      "detail": "颜真卿从 40 岁的多宝塔（线条硬朗、弹性强、直线感强、字形规整、结构严谨）到 70 多岁的颜家庙碑（厚重感越来越强、字有庄严感、正气凛然），后人的形容是「金刚怒目，壮士挥拳」。即便是祭侄文稿里比较纤细的笔画也不给人单薄感，纤细的背后仍然显示浑厚蓬勃有力——这与一般书法家「厚重处厚重、纤细处灵动」的写法完全不同。",
