      "title": "老师引三句儒家书论解释字如其人",
      "font": "隶书",
      "detail": "①「文则数千言乃成其意，书则一字以见其心」（张怀瓘《文字论》）：文章要好几句话才能表述清楚一个意思，书法只要一个字就能看出你是什么样的人。②「书，心画也；心画者，君子小人见矣」：写完一个字就是你精神基础的表现，可以断定是君子还是小人。③「故论书如论象，观书如观人」：看书法就像看一个人的脸。老师说这三句都出自儒家学派，是《书法雅言》这类书里的重要内容，倾向的都是字如其人。",
