      "detail": "原帖中间有一点点断接的痕迹（老师看画面说是手抖了一下，或者中间接了一笔），（字幕此处作「清传」，疑为篆书或隶书）老师接着说允许中间有略微接笔的痕迹；人家写的整篇里有一两处接笔也是被允许的。不需要太钻牛角尖——人不是打印机，肯定会有人的感情上的流露。也不必非得一笔成型，太过一笔成型就没有书写性了；老师建议三点水写完停一下再接，考验接笔技巧，但接得干净自然即可，不需要太注意有没有毛刺。",
