      "font": "隶书",
      "detail": "老师引第一句古文（字幕作「学O病延肥学颜并呕瘦」「学米并照俗学赵病米粽」）讲审美差异：喜欢欧体的人会觉得颜体太肥、太油腻；喜欢颜体的人会觉得欧体太瘦、瘦骨嶙峋、营养不良。米芾个性强烈、生活潇洒；赵孟頫的字以秀美为主、相对拘谨唯美——同样是两个极端。喜欢米芾会觉得赵孟頫中规中矩、有点俗气；学赵孟頫又觉得米芾放纵。老师说这「只是一个选择」，写字时可以有自己倾向的风格，但欣赏上希望「全部都欣赏得了」，把眼光放得再宽一些。",
