      "detail": "老师引第二句古文（字幕作「太还者至而无精」「太极者病而无骨」「横毫侧管则顿慢而肉多」「竖笔之风则干枯而露骨」）作比喻：用笔太缓慢，笔环没有筋道、总体是一摊软肉、没有挺拔感；用笔太快，线条是飘着的，飘在纸面上，并没有踏踏实实地存在于画面之上；侧锋（字幕作「册封」）执笔则笔环特别厚重，厚重到一定程度显得笨拙；写得太细则干枯露骨、很没有筋骨，力量感被削弱得很严重。基本功不够时笔画一旦写特别细，问题尤其明显。",
