      "title": "神气骨肉血：古代的类比评价法，五点各有所指",
      "font": "隶书",
      "detail": "老师从本课作业里选了幾份，用「神气骨肉血」这五点来评估。神＝神态、气＝气韵（国画讲气韵生动，中医讲人体内部运行的无形之气）、骨＝笔画的成立性（是否成立）、肉＝有骨就得有肉、血＝墨里面的水（墨里的成分是肉，水的成分是血）。来源上，最早只有「骨」和「肉」两点；到了苏轼，因为「尸体也是有骨有肉的，不像一个活人」，后来才加上「神、气」。",
      "certainty": "verbatim",
      "font_scope": "通用",
